package app.madigan.antioops;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("antioops")
public interface AntiOopsConfig extends Config
{
	@ConfigItem(
		keyName = "notice",
		name = "Notice",
		description = "",
		position = -2
	)
	default String notice()
	{
		return "Menu Entry Swapper 1-click teleports bypass protection. Use default menu options for full safety.";
	}

	@ConfigItem(
		keyName = "commands",
		name = "Commands",
		description = "",
		position = -1
	)
	default String commands()
	{
		return "::aoprot — protect current instance | ::aoallow — whitelist a teleport | ::aoissue — report a bug";
	}

	@ConfigSection(
		name = "Protection Toggles",
		description = "Which teleport categories to intercept",
		position = 0
	)
	String protectionToggles = "protectionToggles";

	@ConfigSection(
		name = "Custom Zones & Exceptions",
		description = "Custom protected regions and allowed teleports",
		position = 5
	)
	String customSection = "customSection";

	@ConfigSection(
		name = "Behavior",
		description = "How the plugin responds to blocked teleports",
		position = 10
	)
	String behavior = "behavior";

	@ConfigSection(
		name = "Status Overlay",
		description = "Overlay shown on PvP worlds",
		position = 20
	)
	String statusOverlaySection = "statusOverlaySection";

	@ConfigItem(
		keyName = "protectJewelry",
		name = "Protect Jewelry",
		description = "Block jewelry teleports (ring of dueling, games necklace, glory, etc.)",
		position = 1,
		section = protectionToggles
	)
	default boolean protectJewelry()
	{
		return true;
	}

	@ConfigItem(
		keyName = "protectSpellbook",
		name = "Protect Spellbook",
		description = "Block spellbook teleport casts",
		position = 2,
		section = protectionToggles
	)
	default boolean protectSpellbook()
	{
		return true;
	}

	@ConfigItem(
		keyName = "protectPoh",
		name = "Protect POH",
		description = "Block POH portal and house exit actions",
		position = 3,
		section = protectionToggles
	)
	default boolean protectPoh()
	{
		return true;
	}

	@ConfigItem(
		keyName = "protectTablets",
		name = "Protect Tablets",
		description = "Block teleport tablet usage",
		position = 4,
		section = protectionToggles
	)
	default boolean protectTablets()
	{
		return true;
	}

	@ConfigItem(
		keyName = "protectChargedItems",
		name = "Protect Charged Items",
		description = "Block teleports from charged items (lyre, seed pod, sceptres, diary rewards, etc.)",
		position = 5,
		section = protectionToggles
	)
	default boolean protectChargedItems()
	{
		return true;
	}

	@ConfigItem(
		keyName = "customProtectedRegions",
		name = "Custom Protected Regions",
		description = "Region IDs treated as safe. Type ::aoprot in-game to add your current region. HIGHLY recommend doing outside of a PVP world :)",
		position = 6,
		section = customSection
	)
	default String customProtectedRegions()
	{
		return "";
	}

	@ConfigItem(
		keyName = "allowedTeleports",
		name = "Allowed Teleports",
		description = "Teleports that skip confirmation. Type ::aoallow after a blocked teleport to toggle.",
		position = 7,
		section = customSection
	)
	default String allowedTeleports()
	{
		return "";
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "confirmationTimeoutSeconds",
		name = "Confirmation Timeout",
		description = "Seconds to re-click to confirm a blocked teleport",
		position = 11,
		section = behavior
	)
	default int confirmationTimeoutSeconds()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "chatWarnings",
		name = "Chat Warnings",
		description = "Show warning messages in chat when a teleport is blocked",
		position = 12,
		section = behavior
	)
	default boolean chatWarnings()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeHighRisk",
		name = "Include High-Risk Worlds",
		description = "Also protect on high-risk worlds (not just standard PvP worlds)",
		position = 13,
		section = behavior
	)
	default boolean includeHighRisk()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overheadWarning",
		name = "Overhead Warning",
		description = "Show bold overhead text when a teleport is blocked",
		position = 14,
		section = behavior
	)
	default boolean overheadWarning()
	{
		return true;
	}

	@ConfigItem(
		keyName = "warningMessage",
		name = "Warning Message",
		description = "Text shown in overhead warning",
		position = 15,
		section = behavior
	)
	default String warningMessage()
	{
		return "BLOCKED!";
	}

	@ConfigItem(
		keyName = "statusOverlay",
		name = "Enable",
		description = "Show a small overlay with teleport protection status on PvP worlds",
		position = 21,
		section = statusOverlaySection
	)
	default boolean statusOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pvpWorldReminder",
		name = "PvP World Reminder",
		description = "Show a persistent PvP world warning in the status overlay",
		position = 22,
		section = statusOverlaySection
	)
	default boolean pvpWorldReminder()
	{
		return true;
	}
}

package app.madigan.antioops;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

@Singleton
public class AntiOopsOverlay extends Overlay
{
	private static final Duration DISPLAY_DURATION = Duration.ofSeconds(2);
	private static final int Z_OFFSET = 150;

	private final Client client;
	private final AntiOopsConfig config;

	private Instant shownAt = null;

	@Inject
	public AntiOopsOverlay(Client client, AntiOopsConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	public void trigger()
	{
		shownAt = Instant.now();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (shownAt == null)
		{
			return null;
		}

		if (Duration.between(shownAt, Instant.now()).compareTo(DISPLAY_DURATION) > 0)
		{
			shownAt = null;
			return null;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		String text = config.warningMessage();
		if (text == null || text.isEmpty())
		{
			return null;
		}

		Font boldFont = graphics.getFont().deriveFont(Font.BOLD);
		graphics.setFont(boldFont);

		net.runelite.api.Point point = local.getCanvasTextLocation(graphics, text, Z_OFFSET);
		if (point == null)
		{
			return null;
		}

		OverlayUtil.renderTextLocation(graphics, point, text, Color.RED);
		return null;
	}
}

package app.madigan.antioops;

import app.madigan.antioops.classification.TeleportCategory;
import app.madigan.antioops.classification.TeleportClassifier;
import app.madigan.antioops.classification.TeleportTarget;
import app.madigan.antioops.detection.PvpWorldDetector;
import app.madigan.antioops.detection.SafeZoneDetector;
import app.madigan.antioops.interception.InterceptionManager;
import com.google.inject.Provides;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldView;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "PvP Anti-Oops"
)
public class AntiOopsPlugin extends Plugin
{
	private static final String ISSUES_URL = "https://github.com/mads-jm/rl-anti-oops/issues/new?template=item-request.yml";

	@Inject
	private Client client;

	@Inject
	private AntiOopsConfig config;

	@Inject
	private PvpWorldDetector pvpWorldDetector;

	@Inject
	private SafeZoneDetector safeZoneDetector;

	@Inject
	private TeleportClassifier teleportClassifier;

	@Inject
	private InterceptionManager interceptionManager;

	@Inject
	private ConfigManager configManager;

	private String lastBlockedActionKey;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AntiOopsOverlay overlay;

	@Inject
	private AntiOopsStatusOverlay statusOverlay;

	@Override
	protected void startUp() throws Exception
	{
		log.debug("PvP Anti-Oops started!");
		overlayManager.add(overlay);
		overlayManager.add(statusOverlay);
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			pvpWorldDetector.updateWorldType();
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.debug("PvP Anti-Oops stopped!");
		overlayManager.remove(overlay);
		overlayManager.remove(statusOverlay);
		interceptionManager.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			pvpWorldDetector.updateWorldType();
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			pvpWorldDetector.clear();
			interceptionManager.clear();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// 1. Only act on PvP (or high-risk) worlds
		if (!pvpWorldDetector.isPvpWorld(config.includeHighRisk()))
		{
			return;
		}

		// 2. Only block when in a safe zone — prevent accidentally leaving safety
		if (!safeZoneDetector.isInSafeZone())
		{
			return;
		}

		// 3. Classify the click
		TeleportTarget target = teleportClassifier.classify(
			event.getMenuOption(), event.getMenuTarget(), event.getId());
		if (target == null)
		{
			return;
		}

		// 4. Per-category config toggle
		switch (target.getCategory())
		{
			case JEWELRY:
				if (!config.protectJewelry())
				{
					return;
				}
				break;
			case SPELLBOOK:
				if (!config.protectSpellbook())
				{
					return;
				}
				break;
			case POH_PORTAL:
			case POH_EXIT:
				if (!config.protectPoh())
				{
					return;
				}
				break;
			case TABLET:
				if (!config.protectTablets())
				{
					return;
				}
				break;
			case CHARGED_ITEM:
				if (!config.protectChargedItems())
				{
					return;
				}
				break;
			default:
				return;
		}

		// 5. Build action key and check whether to block or allow confirmation
		String actionKey = InterceptionManager.buildActionKey(
			event.getMenuOption(), event.getMenuTarget());

		// 6. Skip if this teleport is on the allowed list
		if (isAllowedTeleport(actionKey))
		{
			return;
		}

		if (interceptionManager.shouldBlock(actionKey))
		{
			lastBlockedActionKey = actionKey;
			event.consume();
			if (config.chatWarnings())
			{
				client.addChatMessage(
					ChatMessageType.GAMEMESSAGE,
					"",
					"<col=ffaa00>[oops]</col> <col=ff0000>Blocked:</col> <col=ffffff>"
						+ target.getName() + "</col>. Click again within "
						+ config.confirmationTimeoutSeconds()
						+ "s to confirm. Type <col=00ff00>::aoallow</col> to whitelist.",
					null);
			}
			if (config.overheadWarning())
			{
				overlay.trigger();
			}
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if ("aoallow".equals(event.getCommand()))
		{
			handleAoallow();
			return;
		}

		if ("aoissue".equals(event.getCommand()))
		{
			LinkBrowser.browse(ISSUES_URL);
			return;
		}

		if (!"aoprot".equals(event.getCommand()))
		{
			return;
		}

		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}

		if (!wv.isInstance())
		{
			chat("[oops] You are not in an instance. Region IDs: "
				+ formatRegions(wv.getMapRegions()));
			return;
		}

		int[] regions = wv.getMapRegions();
		String existing = config.customProtectedRegions().trim();
		java.util.Set<String> regionSet = new java.util.LinkedHashSet<>();
		if (!existing.isEmpty())
		{
			regionSet.addAll(Arrays.asList(existing.split(",")));
		}

		boolean added = false;
		for (int region : regions)
		{
			if (regionSet.add(String.valueOf(region)))
			{
				added = true;
			}
		}

		if (!added)
		{
			chat("[oops] Region already protected: " + formatRegions(regions));
			return;
		}

		String updated = String.join(",", regionSet);
		configManager.setConfiguration("antioops", "customProtectedRegions", updated);
		chat("[oops] Added region to protected list: " + formatRegions(regions)
			+ " (" + regionSet.size() + " total protected regions)");
	}

	private void handleAoallow()
	{
		if (lastBlockedActionKey == null)
		{
			chat("<col=ffaa00>[oops]</col> No recently blocked teleport. Block a teleport first, then type ::aoallow.");
			return;
		}

		Set<String> allowed = getAllowedTeleports();
		String key = lastBlockedActionKey;
		String displayName = formatActionKey(key);

		if (allowed.remove(key))
		{
			String updated = String.join(";", allowed);
			configManager.setConfiguration("antioops", "allowedTeleports", updated);
			chat("<col=ffaa00>[oops]</col> <col=ff0000>Removed</col> from allowed list: <col=ffffff>"
				+ displayName + "</col>. This teleport will be blocked again.");
		}
		else
		{
			allowed.add(key);
			String updated = String.join(";", allowed);
			configManager.setConfiguration("antioops", "allowedTeleports", updated);
			chat("<col=ffaa00>[oops]</col> <col=00ff00>Allowed</col>: <col=ffffff>"
				+ displayName + "</col>. This teleport will no longer be blocked. Type ::aoallow to undo.");
		}
	}

	/**
	 * Converts an internal action key like "rub|ring of dueling(8)" into
	 * a readable display string like "Rub — Ring of dueling(8)".
	 */
	private static String formatActionKey(String actionKey)
	{
		int sep = actionKey.indexOf('|');
		if (sep < 0)
		{
			return actionKey;
		}
		String option = actionKey.substring(0, sep);
		String target = actionKey.substring(sep + 1);
		// Title-case the option, leave target as-is (already readable)
		String displayOption = option.isEmpty() ? "" : Character.toUpperCase(option.charAt(0)) + option.substring(1);
		return displayOption + " \u2014 " + target;
	}

	private boolean isAllowedTeleport(String actionKey)
	{
		return getAllowedTeleports().contains(actionKey);
	}

	private Set<String> getAllowedTeleports()
	{
		String raw = config.allowedTeleports().trim();
		Set<String> set = new LinkedHashSet<>();
		if (!raw.isEmpty())
		{
			for (String entry : raw.split(";"))
			{
				String trimmed = entry.trim().toLowerCase();
				if (!trimmed.isEmpty())
				{
					set.add(trimmed);
				}
			}
		}
		return set;
	}

	private void chat(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
	}

	private static String formatRegions(int[] regions)
	{
		return Arrays.stream(regions)
			.mapToObj(Integer::toString)
			.collect(Collectors.joining(", "));
	}

	@Provides
	AntiOopsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AntiOopsConfig.class);
	}
}

package app.madigan.antioops;

import app.madigan.antioops.detection.PvpWorldDetector;
import app.madigan.antioops.detection.SafeZoneDetector;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

@Singleton
public class AntiOopsStatusOverlay extends OverlayPanel
{
	private final AntiOopsConfig config;
	private final PvpWorldDetector pvpWorldDetector;
	private final SafeZoneDetector safeZoneDetector;

	@Inject
	public AntiOopsStatusOverlay(AntiOopsConfig config, PvpWorldDetector pvpWorldDetector, SafeZoneDetector safeZoneDetector)
	{
		this.config = config;
		this.pvpWorldDetector = pvpWorldDetector;
		this.safeZoneDetector = safeZoneDetector;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.statusOverlay())
		{
			return null;
		}

		if (!pvpWorldDetector.isPvpWorld(config.includeHighRisk()))
		{
			return null;
		}

		if (config.pvpWorldReminder())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("PvP World")
				.leftColor(Color.RED)
				.build());
		}

		boolean safe = safeZoneDetector.isInSafeZone();

		panelComponent.getChildren().add(LineComponent.builder()
			.left("TP Protection:")
			.right(safe ? "ACTIVE" : "OFF")
			.rightColor(safe ? Color.GREEN : Color.RED)
			.build());

		return super.render(graphics);
	}
}

package app.madigan.antioops.classification;

public enum TeleportCategory
{
	JEWELRY,
	SPELLBOOK,
	POH_PORTAL,
	POH_EXIT,
	TABLET,
	CHARGED_ITEM
}

package app.madigan.antioops.classification;

import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Text;

/**
 * Classifies menu click events to determine if they represent a teleport
 * that should be intercepted on PvP worlds.
 */
@Slf4j
@Singleton
public class TeleportClassifier
{
	// ---------- POH object IDs (confirmed in-game) ----------
	// TODO : Fill in missing entries (see ids.md)
	private static final Map<Integer, String> POH_PORTAL_IDS = Map.ofEntries(
		Map.entry(13615, "Varrock"),
		Map.entry(13617, "Falador"),
		Map.entry(13619, "Ardougne"),
		Map.entry(29339, "Lunar Isle"),
		Map.entry(29342, "Waterbirth Island"),
		Map.entry(37586, "Salve Graveyard"),
		Map.entry(37588, "West Ardougne"),
		Map.entry(37591, "Barrows"),
		Map.entry(50713, "Civitas illa Fortis")
	);

	private static final int EXIT_PORTAL_ID = 4525;
	private static final int PORTAL_NEXUS_ID = 33408;

	private static final Set<String> NEXUS_NON_TELEPORT_OPTIONS = Set.of(
		"configuration",
		"examine"
	);

	// ---------- Enchanted jewelry (case-insensitive name-substring match against stripped target) ----------
	// Permissive matching: any option NOT in NON_TELEPORT_OPTIONS + target contains name → JEWELRY
	private static final Set<String> JEWELRY_ITEMS = Set.of(
		"ring of dueling",
		"games necklace",
		"amulet of glory",
		"amulet of eternal glory",
		"ring of wealth",
		"combat bracelet",
		"skills necklace",
		"necklace of passage",
		"digsite pendant",
		"burning amulet",
		"slayer ring",
		"xeric's talisman"
	);

	// ---------- Charged / special teleport items (same permissive matching → CHARGED_ITEM) ----------
	// Quest items, diary rewards, and other non-jewelry teleport items.
	// NOTE: Menu Entry Swapper 1-click teleports bypass classification — the swapped event
	// fires as CC_OP with empty target, so there's no item name to match against.
	// Normal right-click interactions (Rub, Teleport, destination submenus) are caught.
	private static final Set<String> CHARGED_ITEM_NAMES = Set.of(
		"ring of the elements",
		"ring of shadows",
		"pharaoh's sceptre",
		"camulet",
		"ectophial",
		"chronicle",
		"amulet of the eye",
		"pendant of ates",
		"giantsoul amulet",
		"cowbell amulet",
		"explorer's ring",
		"wilderness sword",
		"enchanted lyre",
		"kharedst's memoirs",
		"quetzal whistle",
		"drakan's medallion",
		"ardougne cloak",
		"desert amulet",
		"rada's blessing",
		// "teleport crystal" substring covers both standard and eternal variants
		"teleport crystal"
	);

	// ---------- Specific-option items that can't use permissive matching ----------
	// Single-purpose options with no left-click swapping or destination submenus.
	private static final Map<String, Set<String>> CHARGED_ITEM_SPECIFIC_OPTIONS = Map.ofEntries(
		Map.entry("royal seed pod", Set.of("commune")),
		Map.entry("skull sceptre", Set.of("invoke")),
		Map.entry("dorgesh-kaan sphere", Set.of("break")),
		Map.entry("stony basalt", Set.of("troll stronghold entrance", "troll stronghold roof")),
		Map.entry("icy basalt", Set.of("weiss"))
	);

	// ---------- Menu options that are never teleport actions ----------
	// Shared across jewelry and charged item classification.
	// "check" covers slayer ring + xeric's talisman + quetzal whistle; "features" covers ring of wealth;
	// "dismantle"/"uncharge" cover xeric's talisman; "master"/"partner"/"log" cover slayer ring;
	// "read" covers kharedst's memoirs (lore text, not teleport).
	// "teleport" is intentionally absent — slayer ring's Teleport option IS a real teleport.
	private static final Set<String> NON_TELEPORT_OPTIONS = Set.of(
		"wear",
		"remove",
		"wield",
		"examine",
		"drop",
		"use",
		"check",
		"features",
		"dismantle",
		"uncharge",
		"master",
		"partner",
		"log",
		"read"
	);

	@Inject
	public TeleportClassifier()
	{
	}

	/**
	 * Classifies a menu click event.
	 *
	 * @param menuOption the raw menu option string (e.g. "Cast", "Break", "Rub", "Varrock")
	 * @param menuTarget the raw menu target string — may contain RuneLite color tags
	 * @param itemId     the ID from the event — item ID for inventory actions, object ID for game objects
	 * @return a {@link TeleportTarget} if this is an interceptable teleport, or {@code null}
	 */
	public TeleportTarget classify(String menuOption, String menuTarget, int itemId)
	{
		if (menuOption == null || menuTarget == null)
		{
			return null;
		}

		TeleportTarget result;

		result = classifySpellbook(menuOption, menuTarget);
		if (result != null)
		{
			return result;
		}

		result = classifyJewelry(menuOption, menuTarget);
		if (result != null)
		{
			return result;
		}

		result = classifyTablet(menuOption, menuTarget);
		if (result != null)
		{
			return result;
		}

		result = classifyChargedItem(menuOption, menuTarget);
		if (result != null)
		{
			return result;
		}

		result = classifyPoh(menuOption, menuTarget, itemId);
		if (result != null)
		{
			return result;
		}

		return null;
	}

	private TeleportTarget classifySpellbook(String menuOption, String menuTarget)
	{
		if (!"Cast".equalsIgnoreCase(menuOption))
		{
			return null;
		}

		String stripped = stripTags(menuTarget);

		if (!isTeleportSpell(stripped))
		{
			return null;
		}

		// "Teleport to House" sends the player TO safety — never block it.
		if (stripped.toLowerCase().contains("teleport to house"))
		{
			return null;
		}

		return new TeleportTarget(TeleportCategory.SPELLBOOK, stripped, null);
	}

	/**
	 * Returns true if the stripped spell name looks like a teleport spell.
	 * Mirrors the logic in the AccidentalTeleportBlocker reference plugin.
	 */
	private boolean isTeleportSpell(String strippedTarget)
	{
		String lower = strippedTarget.toLowerCase();
		return lower.contains("teleport") || lower.contains("tele group");
	}

	private TeleportTarget classifyJewelry(String menuOption, String menuTarget)
	{
		String strippedOption = menuOption.trim().toLowerCase();

		// Skip options that are clearly not teleports
		if (NON_TELEPORT_OPTIONS.contains(strippedOption))
		{
			return null;
		}

		String strippedTarget = stripTags(menuTarget).toLowerCase();

		// Check if the target contains a known jewelry item name
		boolean isJewelry = JEWELRY_ITEMS.stream()
			.anyMatch(strippedTarget::contains);

		if (!isJewelry)
		{
			return null;
		}

		// "Rub" = left-click initiates the teleport flow; destination options are also teleports.
		// Both should be intercepted. Everything else (non-teleport options) was already excluded above.
		return new TeleportTarget(TeleportCategory.JEWELRY, strippedTarget, menuOption);
	}

	private TeleportTarget classifyTablet(String menuOption, String menuTarget)
	{
		if (!"Break".equalsIgnoreCase(menuOption))
		{
			return null;
		}

		String strippedTarget = stripTags(menuTarget);
		String lower = strippedTarget.toLowerCase();

		if (!lower.contains("teleport"))
		{
			return null;
		}

		// "Teleport to house" tablets go TO safety — never block them.
		if (lower.contains("teleport to house"))
		{
			return null;
		}

		// Redirected house tablets (e.g. "Rimmington teleport", "Watchtower teleport") are intentionally
		// NOT excluded here — they teleport AWAY from the current location, not to the house interior.
		return new TeleportTarget(TeleportCategory.TABLET, strippedTarget, null);
	}

	private TeleportTarget classifyChargedItem(String menuOption, String menuTarget)
	{
		String optionLower = menuOption.trim().toLowerCase();
		String strippedTarget = stripTags(menuTarget).toLowerCase();

		// Permissive matching: any non-excluded option + known item name in target
		// Handles swapped left-click destinations (Menu Entry Swapper)
		if (!NON_TELEPORT_OPTIONS.contains(optionLower))
		{
			boolean isChargedItem = CHARGED_ITEM_NAMES.stream()
				.anyMatch(strippedTarget::contains);

			if (isChargedItem)
			{
				return new TeleportTarget(TeleportCategory.CHARGED_ITEM, strippedTarget, menuOption);
			}
		}

		// Specific-option matching for items with unique single-purpose teleport options
		for (Map.Entry<String, Set<String>> entry : CHARGED_ITEM_SPECIFIC_OPTIONS.entrySet())
		{
			if (strippedTarget.contains(entry.getKey()) && entry.getValue().contains(optionLower))
			{
				return new TeleportTarget(TeleportCategory.CHARGED_ITEM, strippedTarget, menuOption);
			}
		}

		return null;
	}

	/**
	 * Classifies POH portal, exit portal, and Portal Nexus interactions.
	 *
	 * <p>Covers 9 confirmed portal destinations, the exit portal, and the Portal Nexus.
	 * Additional portal IDs can be added to {@code POH_PORTAL_IDS} as they are verified in-game.
	 *
	 * @param itemId for game object interactions, this is the object ID
	 */
	private TeleportTarget classifyPoh(String menuOption, String menuTarget, int itemId)
	{
		// Exit portal — sends the player out of the POH to wherever they entered from
		if (itemId == EXIT_PORTAL_ID)
		{
			return new TeleportTarget(TeleportCategory.POH_EXIT, "POH Exit Portal", "Previous location");
		}

		// Known destination portals
		String destination = POH_PORTAL_IDS.get(itemId);
		if (destination != null)
		{
			return new TeleportTarget(TeleportCategory.POH_PORTAL, destination + " portal", destination);
		}

		// Portal Nexus — block any teleport interaction, but allow configuration/examine
		if (itemId == PORTAL_NEXUS_ID)
		{
			String optionLower = menuOption.trim().toLowerCase();
			if (NEXUS_NON_TELEPORT_OPTIONS.contains(optionLower))
			{
				return null;
			}
			return new TeleportTarget(TeleportCategory.POH_PORTAL, "Portal Nexus", menuOption);
		}

		return null;
	}

	private static String stripTags(String raw)
	{
		return Text.removeTags(raw);
	}
}

