package app.madigan.antioops.detection;

import java.util.EnumSet;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.WorldType;

@Singleton
public class PvpWorldDetector
{
	private final Client client;

	private boolean pvpWorld = false;
	private boolean highRiskWorld = false;

	@Inject
	public PvpWorldDetector(Client client)
	{
		this.client = client;
	}

	public void updateWorldType()
	{
		EnumSet<WorldType> types = client.getWorldType();
		pvpWorld = types.contains(WorldType.PVP);
		highRiskWorld = types.contains(WorldType.HIGH_RISK);
	}

	public boolean isPvpWorld(boolean includeHighRisk)
	{
		return pvpWorld || (includeHighRisk && highRiskWorld);
	}

	public void clear()
	{
		pvpWorld = false;
		highRiskWorld = false;
	}
}

package app.madigan.antioops.detection;

import app.madigan.antioops.AntiOopsConfig;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.VarbitID;

@Slf4j
@Singleton
public class SafeZoneDetector
{
	private static final int POH_REGION_ID = 8046;

	private final Client client;
	private final AntiOopsConfig config;

	@Inject
	public SafeZoneDetector(Client client, AntiOopsConfig config)
	{
		this.client = client;
		this.config = config;
	}

	/**
	 * Returns true if the player is in a protected area where outbound
	 * teleports should require confirmation.
	 *
	 * <p>This includes both game-designated safe zones (varbit = 0) and
	 * private instances like POH and custom user-added regions where the
	 * player is practically safe despite the varbit reading as dangerous.
	 */
	public boolean isInSafeZone()
	{
		return client.getVarbitValue(VarbitID.PVP_AREA_CLIENT) == 0 || isInPrivateInstance();
	}

	/**
	 * Returns true if the player is in a private instance (POH, boss room,
	 * or custom region) that should be treated as safe even though the PvP
	 * varbit may read as dangerous.
	 */
	private boolean isInPrivateInstance()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || !wv.isInstance())
		{
			return false;
		}

		Set<Integer> protectedRegions = getProtectedRegions();

		for (int region : wv.getMapRegions())
		{
			if (protectedRegions.contains(region))
			{
				return true;
			}
		}

		return false;
	}

	private Set<Integer> getProtectedRegions()
	{
		Set<Integer> regions = new HashSet<>();
		regions.add(POH_REGION_ID);

		String custom = config.customProtectedRegions().trim();
		if (!custom.isEmpty())
		{
			for (String s : custom.split(","))
			{
				try
				{
					regions.add(Integer.parseInt(s.trim()));
				}
				catch (NumberFormatException e)
				{
					log.warn("Invalid region ID in customProtectedRegions: '{}'", s.trim());
				}
			}
		}

		return regions;
	}
}

package app.madigan.antioops.interception;

import app.madigan.antioops.AntiOopsConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.util.Text;

@Singleton
public class InterceptionManager
{
	private final AntiOopsConfig config;
	private final Client client;

	private PendingConfirmation pending = null;

	@Inject
	public InterceptionManager(AntiOopsConfig config, Client client)
	{
		this.config = config;
		this.client = client;
	}

	public boolean shouldBlock(String actionKey)
	{
		long now = System.nanoTime();
		int currentTick = client.getTickCount();

		if (pending != null
			&& pending.actionKey.equals(actionKey)
			&& now < pending.expiresAtNanos
			&& currentTick > pending.blockedOnTick)
		{
			pending = null;
			return false;
		}

		long timeoutNanos = 1_000_000_000L * config.confirmationTimeoutSeconds();
		pending = new PendingConfirmation(actionKey, now + timeoutNanos, currentTick);
		return true;
	}

	public void clear()
	{
		pending = null;
	}

	public static String buildActionKey(String option, String target)
	{
		return (option + "|" + Text.removeTags(target)).toLowerCase();
	}

	private static class PendingConfirmation
	{
		final String actionKey;
		final long expiresAtNanos;
		final int blockedOnTick;

		PendingConfirmation(String actionKey, long expiresAtNanos, int blockedOnTick)
		{
			this.actionKey = actionKey;
			this.expiresAtNanos = expiresAtNanos;
			this.blockedOnTick = blockedOnTick;
		}
	}
}

