	}

	@Test
	public void jewelryExamineReturnsNull()
	{
		TeleportTarget target = classifier.classify("Examine", "<col=ff9040>Games necklace(8)</col>", -1);
		assertNull(target);
	}

	@Test
	public void unknownItemNotClassifiedAsJewelry()
